CREATE TABLE tutor_conversations (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tutor_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_tutor_owner(owner_id,created_at));
CREATE TABLE tutor_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, conversation_id BIGINT NOT NULL, role VARCHAR(12) NOT NULL, content TEXT NOT NULL, sources_json TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_message_conversation FOREIGN KEY(conversation_id) REFERENCES tutor_conversations(id) ON DELETE CASCADE, INDEX idx_message_conversation(conversation_id,created_at));
